public class Loan {
  int tenure;
  double principal;
  float interestRate;
  String accountNumber;

  // Method to calculate EMI
  public double calculateEMI() {
    return (principal * interestRate * tenure) / 100 + principal;
  }
}

public class HomeLoan extends Loan {
  // The subclass automatically inherits all fields and methods of Loan
  HomeLoan() {
    tenure = 5;
    principal = 200000;
    interestRate = 8.5f;
    accountNumber = "Acc12345";
  }

  public static void main(String[] args) {
    HomeLoan hloan = new HomeLoan();
    double emi = hloan.calculateEMI();  // Calling superclass method
    System.out.println("EMI per year: " + emi);
  }
}

