    interestRate = 8.5f;
    accountNo = "Acc12345";
  }

  public static void main(String[] args) {
    HomeLoan hloan = new HomeLoan();
    double emi = hloan.calculateEMI();  // Subclass object calling superclass method
    System.out.println("EMI per year is: " + emi);
  }
}

